    for (cp = binbuf; cp < binbuf + binbuflen; cp++) {
        // Careful, isprint() is locale specific.
        if (0x7f <= *cp ||
            (!isprint(*cp) &&
             !isspace(*cp))) {
            // some non-printable, do it the hard way.
            return gps_hexdump(scbuf, scbuflen, binbuf, binbuflen);
